 {modal==='department'&&<Modal title={departmentEdit?'Edit department':'Add department'} sub="Build your institute’s academic structure." close={()=>setModal(null)}><form onSubmit={async e=>{e.preventDefault();const f=new FormData(e.currentTarget);if(await mutate({action:'department',id:departmentEdit?.id,values:{name:f.get('name'),code:f.get('code'),active:f.get('active')==='1'}},'Department saved.','/api/records'))setModal(null)}}><div className="form-grid"><Field label="Department name *" wide><input name="name" defaultValue={departmentEdit?.name||''} required placeholder="Computer Science & Engineering" maxLength={200}/></Field><Field label="Department code *" wide><input name="code" defaultValue={departmentEdit?.code||''} readOnly={!!departmentEdit} required pattern="[A-Za-z0-9-]{2,12}" placeholder="CSE"/></Field><Field label="Department status"><select name="active" defaultValue={departmentEdit?.active===0?'0':'1'}><option value="1">Active</option><option value="0">Inactive</option></select></Field></div><div className="modal-footer"><button type="button" className="btn" onClick={()=>setModal(null)}>Cancel</button><button className="btn primary" disabled={busy}>Save department</button></div></form></Modal>}
