 {detailTab==='Details'&&<div className="detail-content"><div className="detail-grid">{[['Coordinator',a.coordinator],['Category',a.category],['Activity type',a.type],['Mode',a.mode],['Class / Division',a.class+' / '+a.division],['Semester',a.semester],['Resource person',a.resource||'Not recorded'],['Organization',a.organization||'Not recorded'],['Sponsoring agency',a.sponsor||'Not recorded'],['Budget','₹'+a.budget.toLocaleString('en-IN')],['Academic year',a.year]].map(([k,v])=><div key={k}><small>{k}</small><b>{v}</b></div>)}</div>{[['About this activity',a.description],['Objectives',a.objective],['Learning outcomes',a.outcome]].map(([k,v])=><div className="detail-copy" key={k}><h3>{k}</h3><p>{v||'Not recorded yet.'}</p></div>)}{canEdit(me,a)&&a.status!=='Archived'&&<form className="outcome-form" onSubmit={async e=>{e.preventDefault();const f=new FormData(e.currentTarget);await mutate({action:'outcome',id:a.id,outcome:f.get('outcome')},'Learning outcomes saved.')}}><Field label="Record or update learning outcomes"><textarea key={a.id+a.outcome} name="outcome" defaultValue={a.outcome} rows={3} placeholder="Document the results and impact of this activity." maxLength={4000}/></Field><button className="btn" disabled={busy}>Save outcomes</button></form>}</div>}
